import{_ as e,o as a,c as d,a8 as n}from"./chunks/framework.BqC7ICod.js";const p=JSON.parse('{"title":"Supported languages","description":"randino generates in nine languages, each with its own pools, its own name order and its own romanization. Every generator takes a language, and mixes all of…","frontmatter":{},"headers":[],"relativePath":"guide/languages.md","filePath":"en/guide/languages.md","lastUpdated":1788615057000}'),s={name:"guide/languages.md"};function i(o,t,r,l,h,c){return a(),d("div",null,[...t[0]||(t[0]=[n(`<h1 id="supported-languages" tabindex="-1">Supported languages <a class="header-anchor" href="#supported-languages" aria-label="Permalink to &quot;Supported languages&quot;">​</a></h1><p>randino generates in nine languages, each with its own pools, its own name order and its own romanization. Every generator takes a language, and mixes all of the ones it supports when you leave it out.</p><table tabindex="0"><thead><tr><th>Code</th><th>Language</th><th>Native</th><th style="text-align:center;">Person names</th><th style="text-align:center;">Words and nicknames</th><th style="text-align:center;">Sentences</th></tr></thead><tbody><tr><td><code>en</code></td><td>English</td><td>English</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><code>ko</code></td><td>Korean</td><td>한국어</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><code>ja</code></td><td>Japanese</td><td>日本語</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><code>zh</code></td><td>Chinese</td><td>中文</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><code>it</code></td><td>Italian</td><td>Italiano</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><code>de</code></td><td>German</td><td>Deutsch</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><code>ru</code></td><td>Russian</td><td>Русский</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><code>es</code></td><td>Spanish</td><td>Español</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr><tr><td><code>vi</code></td><td>Vietnamese</td><td>Tiếng Việt</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td><td style="text-align:center;">✅</td></tr></tbody></table><div class="randino-lang" data-lang="js"><p>The codes are string literals, and they are also available at runtime as <code>NAME_LANGUAGES</code> and <code>WORD_LANGUAGES</code>.</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { NAME_LANGUAGES, WORD_LANGUAGES } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;randino&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NAME_LANGUAGES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// [&#39;en&#39;, &#39;ko&#39;, &#39;ja&#39;, &#39;zh&#39;, &#39;it&#39;, &#39;de&#39;, &#39;ru&#39;, &#39;es&#39;, &#39;vi&#39;]</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">WORD_LANGUAGES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// [&#39;en&#39;, &#39;ko&#39;, &#39;ja&#39;, &#39;zh&#39;, &#39;vi&#39;, &#39;es&#39;, &#39;it&#39;, &#39;de&#39;, &#39;ru&#39;]</span></span></code></pre></div></div><div class="randino-lang" data-lang="dart"><p>The codes are the members of two enums, and the lists are also available as <code>nameLanguages</code> and <code>wordLanguages</code>.</p><div class="language-dart vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dart</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;package:randino/randino.dart&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NameLanguage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.ko.name; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &#39;ko&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">nameLanguages; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// every NameLanguage, in presentation order</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">wordLanguages; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// every WordLanguage, in presentation order</span></span></code></pre></div></div><div class="randino-lang" data-lang="py"><p>The codes are <code>Literal</code> types, so a checker rejects a code that does not exist, and the tuples are also available at runtime as <code>NAME_LANGUAGES</code> and <code>WORD_LANGUAGES</code>.</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> randino </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> NAME_LANGUAGES</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">WORD_LANGUAGES</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NAME_LANGUAGES</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # (&#39;en&#39;, &#39;ko&#39;, &#39;ja&#39;, &#39;zh&#39;, &#39;it&#39;, &#39;de&#39;, &#39;ru&#39;, &#39;es&#39;, &#39;vi&#39;)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">WORD_LANGUAGES</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # (&#39;en&#39;, &#39;ko&#39;, &#39;ja&#39;, &#39;zh&#39;, &#39;vi&#39;, &#39;es&#39;, &#39;it&#39;, &#39;de&#39;, &#39;ru&#39;)</span></span></code></pre></div></div><h2 id="person-names" tabindex="-1">Person names <a class="header-anchor" href="#person-names" aria-label="Permalink to &quot;Person names&quot;">​</a></h2><p>Each language decides three things: which part of a name comes first, whether there is a middle part at all, and how the native form becomes an English pronunciation.</p><table tabindex="0"><thead><tr><th>Code</th><th>Name order</th><th>Middle name</th><th>Example</th></tr></thead><tbody><tr><td><code>en</code></td><td>given first</td><td>yes</td><td>Paisley Lewis</td></tr><tr><td><code>ko</code></td><td>family first</td><td>no</td><td>김태윤 → Kim Taeyun</td></tr><tr><td><code>ja</code></td><td>family first</td><td>no</td><td>山口直人 → Yamaguchi Naoto</td></tr><tr><td><code>zh</code></td><td>family first</td><td>no</td><td>赵勇轩 → Zhao Yongxuan</td></tr><tr><td><code>it</code></td><td>given first</td><td>yes</td><td>Giorgia Mancini</td></tr><tr><td><code>de</code></td><td>given first</td><td>yes</td><td>Johanna Wolf</td></tr><tr><td><code>ru</code></td><td>given first</td><td>yes (patronymic)</td><td>Иван Семёнов → Ivan Semyonov</td></tr><tr><td><code>es</code></td><td>given first</td><td>yes</td><td>Gonzalo Martín → Gonzalo Martin</td></tr><tr><td><code>vi</code></td><td>family first</td><td>yes</td><td>Đặng Quân → Dang Quan</td></tr></tbody></table><p>Korean, Japanese and Chinese have no middle part, so the middle-name option is ignored for them rather than inventing one. There is a helper that answers that question directly: <a href="./../name/name-supports-middle-name"><code>nameSupportsMiddleName</code></a>.</p><h3 id="romanization" tabindex="-1">Romanization <a class="header-anchor" href="#romanization" aria-label="Permalink to &quot;Romanization&quot;">​</a></h3><p>Romanization is the <strong>English pronunciation of the native form</strong>, not a translation, and each script gets there its own way:</p><ul><li><strong>Latin scripts</strong> drop their diacritics: <code>Pérez</code> → <code>Perez</code>, <code>Müller</code> → <code>Muller</code>, <code>Đỗ</code> → <code>Do</code>.</li><li><strong>Cyrillic</strong> is transliterated character by character: <code>Семёнов</code> → <code>Semyonov</code>.</li><li><strong>Korean</strong> follows the Revised Romanization of Korean, including the sound changes between syllables — <code>석민</code> is <code>Seongmin</code> and not <code>Seokmin</code> — with the conventional spelling for surnames, so <code>김</code> is <code>Kim</code> rather than <code>Gim</code>.</li><li><strong>Japanese and Chinese</strong> carry the reading on each character, so <code>佐藤</code> is <code>Sato</code> and <code>王</code> is <code>Wang</code>.</li></ul><p>English is the one language where romanizing changes nothing, because the names are already in the Latin alphabet.</p><h2 id="words-and-nicknames" tabindex="-1">Words and nicknames <a class="header-anchor" href="#words-and-nicknames" aria-label="Permalink to &quot;Words and nicknames {#words-and-nicknames}&quot;">​</a></h2><p>The word pools cover every one of the nine, and so do <code>randWord</code>, the twenty-five themed generators and <code>randNickname</code>. What differs between the languages is where the modifier goes and whether it changes shape beside the noun, and each language says both in its own frames and agreement rules.</p><table tabindex="0"><thead><tr><th>Code</th><th>Language</th><th>Shapes</th><th>Example</th></tr></thead><tbody><tr><td><code>ko</code></td><td>Korean</td><td>modifier, trailing word</td><td>멋진사자, 고양이꼬리</td></tr><tr><td><code>en</code></td><td>English</td><td>modifier, trailing word</td><td>MistyOwl, CatTail</td></tr><tr><td><code>ja</code></td><td>Japanese</td><td>modifier (attributive form)</td><td>青いライオン, 星の影</td></tr><tr><td><code>zh</code></td><td>Chinese</td><td>modifier, 的 before a verb</td><td>快乐熊猫, 奔跑的狮子</td></tr><tr><td><code>vi</code></td><td>Vietnamese</td><td>modifier <strong>after</strong> the noun</td><td>mèo xanh, đuôi mèo</td></tr><tr><td><code>es</code></td><td>Spanish</td><td>modifier after, <strong>agreeing</strong></td><td>gato azul, luna dorada</td></tr><tr><td><code>it</code></td><td>Italian</td><td>modifier after, <strong>agreeing</strong></td><td>gatto azzurro, luna dorata</td></tr><tr><td><code>de</code></td><td>German</td><td>modifier <strong>before</strong>, declining</td><td>blauer Wal, blaue Katze</td></tr><tr><td><code>ru</code></td><td>Russian</td><td>modifier <strong>before</strong>, declining</td><td>синий кит, синяя рыба</td></tr></tbody></table><p>The shapes belong to the language, so Vietnamese writes its own: the modifier behind the noun, the possessed thing in front of its owner. A language that inflects tags each noun with its gender and lists the endings a modifier changes, so Spanish writes <code>gato dorado</code> beside <code>luna dorada</code> without either form being stored twice. A noun with no singular at all, such as <code>ножницы</code>, <code>gafas</code> or <code>Jeans</code>, is tagged plural instead, because no singular modifier can stand beside it.</p><p>Every language the name generator knows has word pools too, so <code>language</code> means the same nine codes on every generator in the package.</p><p>Japanese and Chinese reach a second noun only through の and 的. A bare noun-noun compound needs a particle more often than not in either language, and reads as garbled once the base word is abstract.</p><h2 id="sentences" tabindex="-1">Sentences <a class="header-anchor" href="#sentences" aria-label="Permalink to &quot;Sentences&quot;">​</a></h2><p>Every language writes sentences too, and each declares the shapes its own grammar can carry. What differs is where the verb stands, how a phrase is marked, and which shapes the language can write at all.</p><table tabindex="0"><thead><tr><th>Code</th><th>Language</th><th>Shapes it declares</th><th>A sentence</th></tr></thead><tbody><tr><td><code>ko</code></td><td>Korean</td><td>every one, verb last</td><td>검은 고양이가 숲에서 잠잔다.</td></tr><tr><td><code>ja</code></td><td>Japanese</td><td>every one, verb last</td><td>ハンバーガーが暗礁で冷める。</td></tr><tr><td><code>zh</code></td><td>Chinese</td><td>every one, place before the verb</td><td>巨乌贼又品尝朱红椰汁。</td></tr><tr><td><code>en</code></td><td>English</td><td>every one, verb second</td><td>The angler cleans the towel in the balcony.</td></tr><tr><td><code>vi</code></td><td>Vietnamese</td><td>every one, verb second</td><td>Lông mi run trong khe núi.</td></tr><tr><td><code>es</code></td><td>Spanish</td><td>every one, verb second</td><td>La vía láctea brilla en la roca pobre.</td></tr><tr><td><code>it</code></td><td>Italian</td><td>every one, place without article</td><td>Il birraio audace dimentica l&#39;eclissi.</td></tr><tr><td><code>de</code></td><td>German</td><td>no object, no place</td><td>Im Frühling blüht eine Chrysantheme noch.</td></tr><tr><td><code>ru</code></td><td>Russian</td><td>no object, no place</td><td>Спутанный юпитер едва светлеет.</td></tr></tbody></table><p>German and Russian are narrower for the same reason. Both would put an object in the accusative and a place in another case again, and each case changes the noun&#39;s own ending or the article in front of it, so they do not declare the shapes that need one. Asking for one falls back to the closest they have. <a href="./../sentence/">Sentences</a> covers this in full.</p>`,24)])])}const u=e(s,[["render",i]]);export{p as __pageData,u as default};
